// Jobs = (MSK day × report kind). Schedule: yesterday MSK. Temporary webhook (backfill): {from_day,to_day,run_mode}.
const src = $input.first().json || {};
const body = src.body || {};
const mskNow = new Date(Date.now() + 3*3600*1000);
const y = new Date(mskNow.getTime() - 24*3600*1000).toISOString().slice(0,10);
let fromDay = y, toDay = y, mode = 'schedule';
if (body.from_day) { fromDay = String(body.from_day); toDay = String(body.to_day || body.from_day); mode = String(body.run_mode || 'backfill'); }
const re = /^\d{4}-\d{2}-\d{2}$/;
if (!re.test(fromDay) || !re.test(toDay) || fromDay > toDay || toDay > y) throw new Error('bad day range '+fromDay+'..'+toDay);
const out = [];
for (let d = new Date(fromDay+'T00:00:00Z'); d <= new Date(toDay+'T00:00:00Z'); d = new Date(d.getTime()+86400000)) {
  for (const kind of ['products','orders']) out.push({ json: { report_day: d.toISOString().slice(0,10), kind, run_mode: mode } });
}
if (out.length > 140) throw new Error('range too long: '+out.length);
return out;

// Pay-per-order, all products (campaign PPO_CAMPAIGN_ID), ONE MSK day, one report kind per job:
//   products: GET /api/client/statistics/all_sku_promo/products/generate/json (day: expense, orders/sales search+recs)
//   orders:   GET /api/client/statistics/all_sku_promo/orders/generate/json   (per order: SKU, offer id, price, bid, expense)
// n8n Cloud Code task limit = 60 s, so each call is bounded to ~52 s worst case and
// returns state PENDING / RATE_LIMITED (workflow waits 15 s and calls again) or DONE (-> Insert receipt).
const j = $json.state ? { ...$json } : { ...$('Loop Jobs').first().json, empty_retry: Number($json.empty_retry || 0),
  report_uuid: null, order_attempts: 0, poll_attempts: 0, order_http_status: null };
if ($json.reset_for_retry) { Object.assign(j, { ...$('Loop Jobs').first().json, empty_retry: 1, report_uuid: null, order_attempts: 0, poll_attempts: 0, order_http_status: null }); }
const token = $('Get Performance Token').first().json.access_token;
const base = 'https://api-performance.ozon.ru';
const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const deadline = Date.now() + 25000; // worst case: order 15 s + poll to ~32 s + download 20 s < 60 s task limit
const KINDS = { products: '/api/client/statistics/all_sku_promo/products/generate/json',
                orders:   '/api/client/statistics/all_sku_promo/orders/generate/json' };
const PATH = KINDS[j.kind];
const prev = new Date(Date.parse(j.report_day + 'T00:00:00Z') - 86400000).toISOString().slice(0,10);
const q = { 'timeBounds.from': prev + 'T21:00:00Z', 'timeBounds.to': j.report_day + 'T20:59:59Z' }; // = MSK day 00:00:00..23:59:59
const auth = { Authorization: 'Bearer ' + token, Accept: 'application/json' };
Object.assign(j, { request_body: { kind: j.kind, method: 'GET', path: PATH, query: q }, workflow_id: $workflow.id, execution_id: String($execution.id),
  final_state: null, download_http_status: null, body_b64: null, parsed_row_count: null, error_text: null });
try {
  if (!j.report_uuid) {
    j.order_attempts = (j.order_attempts || 0) + 1;
    const r = await this.helpers.httpRequest({ method: 'GET', url: base + PATH, headers: auth, qs: q, json: true,
      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 15000 });
    j.order_http_status = r.statusCode;
    if (r.statusCode === 429 || r.statusCode >= 500) {
      if (j.order_attempts >= 5) { j.final_state = 'ORDER_HTTP_' + r.statusCode; j.state = 'DONE'; return [{ json: j }]; }
      j.state = 'RATE_LIMITED'; return [{ json: j }];
    }
    const ob = typeof r.body === 'string' ? (() => { try { return JSON.parse(r.body); } catch (e) { return { raw: r.body }; } })() : r.body;
    j.report_uuid = (ob && (ob.UUID || ob.uuid)) || null;
    if (!j.report_uuid) { j.final_state = 'ORDER_FAILED'; j.error_text = JSON.stringify(ob).slice(0, 2000); j.state = 'DONE'; return [{ json: j }]; }
  }
  let st = null;
  while (Date.now() + 6000 < deadline) {
    await sleep(5000);
    j.poll_attempts = (j.poll_attempts || 0) + 1;
    const s = await this.helpers.httpRequest({ method: 'GET', url: base + '/api/client/statistics/' + j.report_uuid,
      headers: auth, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 8000 });
    if (s.statusCode === 429 || s.statusCode >= 500) { continue; }
    const sb = typeof s.body === 'string' ? JSON.parse(s.body) : s.body;
    st = sb && sb.state;
    if (st === 'ERROR') { j.error_text = JSON.stringify(sb).slice(0, 2000); break; }
    if (st === 'OK') break;
  }
  if (st === 'ERROR') { j.final_state = 'REPORT_ERROR'; j.state = 'DONE'; return [{ json: j }]; }
  if (st !== 'OK') {
    // n8n Cloud caps an execution at 5 min: give up after ~2 min and record POLL_TIMEOUT (then one retry)
    if (j.poll_attempts >= 16) { j.final_state = 'POLL_TIMEOUT'; j.state = 'DONE'; } else { j.state = 'PENDING'; }
    return [{ json: j }];
  }
  const d = await this.helpers.httpRequest({ method: 'GET', url: base + '/api/client/statistics/report',
    qs: { UUID: j.report_uuid }, headers: auth, encoding: 'arraybuffer', json: false,
    returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  j.download_http_status = d.statusCode;
  const buf = Buffer.from(d.body);
  j.body_b64 = buf.toString('base64');
  let n = 0;
  try { const b = JSON.parse(buf.toString('utf8')); n = Array.isArray(b.rows) ? b.rows.length : 0; }
  catch (e) { j.error_text = 'body not JSON: ' + e.message; }
  j.parsed_row_count = n;
  j.final_state = d.statusCode === 200 ? (n > 0 ? 'OK_ROWS' : 'OK_EMPTY') : 'DOWNLOAD_HTTP_' + d.statusCode;
  j.state = 'DONE';
} catch (e) {
  j.final_state = 'EXCEPTION'; j.error_text = String(e && e.message || e).slice(0, 2000); j.state = 'DONE';
}
return [{ json: j }];
